function parseClaudeJson(text) {
  const raw = String(text || '').trim();
  const fenced = raw.match(/\x60\x60\x60(?:json)?\s*([\s\S]*?)\x60\x60\x60/);
  const candidate = fenced ? fenced[1] : raw.slice(raw.indexOf('{'), raw.lastIndexOf('}') + 1);
  try {
    return JSON.parse(candidate);
  } catch (e) {
    throw new Error('Claude did not return valid JSON. Raw reply: ' + raw.slice(0, 500));
  }
}
function esc(s) {
  return String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}
const email = parseClaudeJson($json.text);
const lead = $('Add a Lead').first().json;
return [{ json: { to: lead.Email.trim().toLowerCase(), subject: email.subject, body: email.body } }];

const lead = $('Add a Lead').first().json;
const first = $('Prepare First Email').first().json;
const store = $getWorkflowStaticData('global');
store.leads = store.leads || {};
store.leads[first.to] = {
  name: lead.Name,
  email: first.to,
  company: lead.Company || '',
  context: lead['Why them'],
  subject: first.subject,
  added_at: new Date().toISOString(),
  last_draft_at: new Date().toISOString(),
  status: 'active',
};
return [{ json: { saved: first.to, active_leads: Object.values(store.leads).filter((l) => l.status === 'active').length } }];

const store = $getWorkflowStaticData('global');
const limit = Number($('Config: Agent Settings').first().json.max_leads_checked_per_day) || 40;
const leads = Object.values(store.leads || {})
  .filter((l) => l.status === 'active')
  .sort((a, b) => new Date(a.last_draft_at) - new Date(b.last_draft_at))
  .slice(0, limit);
if (!leads.length) return [];
const terms = leads.map((l) => 'from:' + l.email + ' to:' + l.email).join(' ');
const query = '{' + terms + '} newer_than:120d';
return leads.map((l) => ({ json: { ...l, gmail_query: query } }));

const settings = $('Config: Agent Settings').first().json;
const store = $getWorkflowStaticData('global');
const leads = $('Load Active Leads').all().map((i) => i.json);
const messages = $input.all().map((i) => i.json).filter((m) => m && m.id);

const emailsIn = (v) => (JSON.stringify(v ?? '').toLowerCase().match(/[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}/g) || []);
const dateOf = (m) => {
  if (m.internalDate) return new Date(Number(m.internalDate));
  const d = m.Date || m.date || m.headers?.date;
  return d ? new Date(d) : new Date(0);
};
const labelsOf = (m) => m.labelIds || (m.labels || []).map((l) => l.id);
const DAY = 24 * 60 * 60 * 1000;
const out = [];

for (const lead of leads) {
  const fromLead = messages.filter((m) => emailsIn(m.From ?? m.from).includes(lead.email) && !labelsOf(m).includes('SENT'));
  const sent = messages
    .filter((m) => labelsOf(m).includes('SENT') && emailsIn(m.To ?? m.to).includes(lead.email))
    .sort((a, b) => dateOf(a) - dateOf(b));

  if (fromLead.length) {
    store.leads[lead.email].status = 'replied';
    continue;
  }
  if (!sent.length) continue;

  const followUpsSent = sent.length - 1;
  if (followUpsSent >= Number(settings.max_follow_ups)) {
    store.leads[lead.email].status = 'finished';
    continue;
  }

  const lastSent = dateOf(sent[sent.length - 1]);
  const pendingDraft = new Date(lead.last_draft_at) > lastSent;
  const due = Date.now() - lastSent.getTime() >= Number(settings.follow_up_after_days) * DAY;
  if (pendingDraft || !due) continue;

  out.push({ json: {
    ...lead,
    follow_up_number: followUpsSent + 1,
    is_last: followUpsSent + 1 >= Number(settings.max_follow_ups),
    thread_id: sent[0].threadId,
    days_since_last: Math.floor((Date.now() - lastSent.getTime()) / DAY),
  } });
}
return out;

